-- Resources: seven linked workflow overviews, retaining existing detailed articles.

select private.rc_release_guide(
 p_slug => 'bookings-workflow-overview',
 p_tool_key => 'bookings',
 p_title => 'Bookings: from request to settlement',
 p_summary => 'Understand pricing, capacity, delivery and settlement.',
 p_screen_keys => array['bookings.requests','bookings.calendar','bookings.project'],
 p_sort_order => 5,
 p_version_note => 'Workflow overview: first release',
 p_body => $body${"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. How Bookings works"}]},{"type":"paragraph","content":[{"type":"text","text":"Bookings helps WUWF answer three questions before accepting production work: "},{"type":"text","text":"Can we deliver it? What will it cost? Who will pay for it?","marks":[{"type":"bold"}]},{"type":"text","text":" It also records what actually happened so the station can evaluate its commitments and recover appropriate costs."}]},{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"request","marks":[{"type":"bold"}]},{"type":"text","text":" identifies the partner, work, dates, and rate. An "},{"type":"text","text":"estimate","marks":[{"type":"bold"}]},{"type":"text","text":" prices the requested services using a versioned rate card. A "},{"type":"text","text":"booking","marks":[{"type":"bold"}]},{"type":"text","text":" occupies a specific pool and time window and draws on production capacity. An "},{"type":"text","text":"agreement","marks":[{"type":"bold"}]},{"type":"text","text":", where applicable, records longer-term commitments and may reserve windows for a partner. A "},{"type":"text","text":"settlement","marks":[{"type":"bold"}]},{"type":"text","text":" records actual cost and the amount recharged or invoiced after delivery."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The two constraints are different"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Production capacity","marks":[{"type":"bold"}]},{"type":"text","text":" is tracked by labor class and available time. A term plan records the hours available for production work, any reserve for strategic university work, and the facilities or service pools that may be booked. Core duties that have already been excluded from the available-hours figure must not also be entered as dated holds, or capacity is deducted twice."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Airtime capacity","marks":[{"type":"bold"}]},{"type":"text","text":" is derived from eligible opportunities in On Air's clocks, with the university contribution reflected in the term plan. Bookings reports this envelope; it does "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" place on-air announcements. Actual placement belongs in Traffic or On Air."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Three pricing situations"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"University rate:","marks":[{"type":"bold"}]},{"type":"text","text":" a university unit pays the modeled cost under the applicable rate card."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"University rate (WUWF contributing):","marks":[{"type":"bold"}]},{"type":"text","text":" eligible strategic/applied-learning work uses a protected professional labor reserve; the partner still pays the elements charged under that rate, such as student labor and equipment."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Outside rate:","marks":[{"type":"bold"}]},{"type":"text","text":" external work uses the outside rate, including the applicable assessment and margin."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"These are pricing treatments, not judgments about whether a project is worthwhile. Strategic status does not create unlimited capacity: when the reserve cannot cover the professional time requested, the system can price the work at the university rate and flag the limitation."}]},{"type":"paragraph","content":[{"type":"text","text":"Distinguish four figures.","marks":[{"type":"bold"}]},{"type":"text","text":" *Modeled cost* estimates WUWF's resources for the work. *Quoted amount* is what the partner is expected to pay. *Actual cost* is reconstructed from confirmed labor, equipment and direct expenses after delivery. *WUWF contribution* is the portion of actual cost not covered by the partner's payment, floored at zero. Do not call the quoted amount WUWF's cost or treat capacity hours as invoice amounts."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"What a term plan means"}]},{"type":"paragraph","content":[{"type":"text","text":"A term plan is a bounded planning period, not a claim that every staff hour is available for outside projects. Operations enters the professional time genuinely available for production after routine core obligations, and records dated holds for additional known conflicts. Protected capacity is set per labor class, not as a blanket percentage of all labor. A labor class without a reserve draws ordinary open capacity even on a strategic booking."}]},{"type":"paragraph","content":[{"type":"text","text":"The deployed capacity model permits multiple active, nonoverlapping plans, selects the term by booking date, and makes closed terms final."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. Handle a new production request"}]},{"type":"paragraph","content":[{"type":"text","text":"The simplest path should be the default. Use a university production request—such as coverage or event support requested by Athletics—as the running example; do not imply that Athletics has a blanket agreement or an approved contribution."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Before opening the form"}]},{"type":"paragraph","content":[{"type":"text","text":"Clarify the requesting unit or organization; the intended deliverable; event date and location; whether facilities, field production, editing, or live support are needed; the responsible WUWF production lead; and any known approval, distribution, or access requirements. If any of those remain uncertain, record an assumption rather than treating it as confirmed scope."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Enter, price, and check dates"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"In "},{"type":"text","text":"**Bookings → Requests**","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/bookings/requests"}}]},{"type":"text","text":", select "},{"type":"text","text":"**+ New request**","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/bookings/requests/new"}}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Identify the partner, select the requested service, and enter the event date and required information. For a university request, answer the strategic/applied-learning question only when that classification has actually been decided."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Create and price the estimate","marks":[{"type":"bold"}]},{"type":"text","text":". The request and its estimate are created together. Review the summary: work, partner amount, WUWF contribution, required time, date feasibility and estimate expiry."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open "},{"type":"text","text":"Show calculation","marks":[{"type":"bold"}]},{"type":"text","text":" if you need to understand the rate version, labor and equipment assumptions or how the quoted amount was derived. These details are for review, not values to change casually."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If "},{"type":"text","text":"The dates need attention","marks":[{"type":"bold"}]},{"type":"text","text":" appears, read the specific reason and assess the offered alternative dates with the partner and production lead. Never assume a date is committed solely because it appears on the request."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If the actual work differs from the standard package, use "},{"type":"text","text":"Adjust scope","marks":[{"type":"bold"}]},{"type":"text","text":". Record the revised hours, facilities, crew or dates explicitly; once dates are manually adjusted, the automatic date planner no longer manages them."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Before sending an estimate:","marks":[{"type":"bold"}]},{"type":"text","text":" Check that the package actually describes the work, that dates and capacity are feasible, that the rate treatment is defensible, and that the request identifies what the partner will receive. A displayed estimate is not itself agreement to perform the work."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"From estimate to delivery"}]},{"type":"paragraph","content":[{"type":"text","text":"The existing request workflow distinguishes estimate, planning, date holds, commitments, delivery and settlement. Follow the controls and approvals for the request's current stage. Tentative bookings reserve their windows and have a limited lifetime; do not promise permanent availability on the strength of a tentative hold. Where an agreement reserves blocks, verify that the requested use falls within the agreement and its release deadlines."}]},{"type":"paragraph","content":[{"type":"text","text":"Handoff:","marks":[{"type":"bold"}]},{"type":"text","text":" The production lead confirms the practical schedule, resources and completed work. The person authorized to approve the commitment confirms acceptance before dates and service terms are treated as firm. Finance is responsible for the settlement record, not for reconstructing production hours from guesswork."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"When something changes"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Scope or timing changes before delivery:","marks":[{"type":"bold"}]},{"type":"text","text":" update the request, rerun the relevant checks, and communicate any changed estimate or availability before proceeding."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Conflict or exhausted capacity:","marks":[{"type":"bold"}]},{"type":"text","text":" consult the reason and alternate dates; do not invent capacity by overlooking a blackout or protected reserve. Booking exceptions require the Executive Director and are audited."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Work beyond the approved estimate:","marks":[{"type":"bold"}]},{"type":"text","text":" record the additional effort in actuals. The settlement calculation does not automatically increase the partner's agreed charge just because staff spent more time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cancellation or a mistake:","marks":[{"type":"bold"}]},{"type":"text","text":" check the request's stage and relevant booking/agreement controls before releasing dates; do not assume a posted finance record can be reversed inside Bookings."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. Plan and govern production capacity"}]},{"type":"paragraph","content":[{"type":"text","text":"Owner:","marks":[{"type":"bold"}]},{"type":"text","text":" Operations; executive approval or policy decisions where required. This guide explains the model, not a substitute for annual or term planning conversations."}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Establish the planning period.","marks":[{"type":"bold"}]},{"type":"text","text":" Identify the dates, expected university commitments, likely external demand, staffing and facility constraints. The term is the unit in which capacity is committed and reported."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enter realistic available hours.","marks":[{"type":"bold"}]},{"type":"text","text":" For each labor class, enter the production hours remaining after routine core duties. Do not begin with payroll hours and treat them as entirely bookable. Record known assumptions so the figure can be explained later."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Assign reserves deliberately.","marks":[{"type":"bold"}]},{"type":"text","text":" Apply a reserve share only to classes whose professional time WUWF intends to contribute to strategic work. A class with no reserve still needs enough open hours for every booking, including strategic work that uses that class."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Configure pools and windows.","marks":[{"type":"bold"}]},{"type":"text","text":" Define how many units of each studio, field, live or editing pool can be used and when a booking can take them. A pool is an availability constraint, not an invoice line by itself."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Record dated exclusions.","marks":[{"type":"bold"}]},{"type":"text","text":" Use blackouts for dates closed to partner work and holds for specific WUWF uses. Avoid double counting work already excluded from the hours entered above."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Test representative requests.","marks":[{"type":"bold"}]},{"type":"text","text":" Check an ordinary university production request, an eligible strategic request, an external request and a day with competing uses. Confirm that both the labor-class capacity and the pool window permit the proposed work."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Review commitments periodically.","marks":[{"type":"bold"}]},{"type":"text","text":" Compare bookings and holds with remaining open capacity, and the airtime envelope with actual on-air commitments. Escalate policy questions—such as releasing unused strategic reserve—rather than silently changing the plan to accommodate one request."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Do not conflate reserve with discounted pricing.","marks":[{"type":"bold"}]},{"type":"text","text":" Reserve protects a defined amount of professional time. The rate treatment follows both strategic eligibility and available reserve. Likewise, a partner's payment does not guarantee an available studio or staff member."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Close and settle a delivered request"}]},{"type":"paragraph","content":[{"type":"text","text":"Owner:","marks":[{"type":"bold"}]},{"type":"text","text":" Production confirms actual resource use; Finance drafts and posts the settlement."}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mark the request delivered through its established workflow only after confirming the agreed service was provided."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Confirm actual labor hours for each planned class and resource use for each planned pool. Settlement drafting is blocked until required confirmation is complete."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"In the request's "},{"type":"text","text":"Settlement","marks":[{"type":"bold"}]},{"type":"text","text":" section, review the draft. The partner amount starts from the approved estimate, replacing estimated direct expenses with recorded actual expenses. Actual labor and resource use determine "},{"type":"text","text":"cost to WUWF","marks":[{"type":"bold"}]},{"type":"text","text":", not an automatic increase to the partner's charge."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enter actual direct expenses, a funding index for a university recharge or the relevant invoice information for an external partner, and explanatory notes as appropriate."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"Update the draft","marks":[{"type":"bold"}]},{"type":"text","text":" to recalculate from the latest confirmed actuals; compare the amount, actual cost, and contribution with the estimate."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Record the transaction in the university's financial system according to Finance's process. Enter the journal entry number, then "},{"type":"text","text":"Post the settlement","marks":[{"type":"bold"}]},{"type":"text","text":" in Bookings. Posting makes the settlement final."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Important limitations:","marks":[{"type":"bold"}]},{"type":"text","text":" The repository design explicitly defers Banner integration, PDF invoicing, and reversal of posted settlements. Do not describe those actions as available within Bookings. A correction to a posted record needs the applicable Finance procedure outside the ordinary edit workflow."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Direct portal screen links"}]},{"type":"paragraph","content":[{"type":"text","text":"Open these routes in the portal. Individual records must be opened from their list; no record ID is assumed."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Requests","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/bookings/requests"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"New request","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/bookings/requests/new"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Calendar","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/bookings/calendar"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Term plan","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/bookings/calendar/plan"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Rate card","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/bookings/rates/card"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Term report","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/bookings/report"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Partners","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/bookings/partners"}}]}]}]}]}]}$body$
);

select private.rc_release_guide(
 p_slug => 'traffic-workflow-overview',
 p_tool_key => 'underwriting',
 p_title => 'Traffic: from order to affidavit',
 p_summary => 'Follow obligations through copy, placement and reconciliation.',
 p_screen_keys => array['underwriting.contracts','underwriting.copy','underwriting.exceptions'],
 p_sort_order => 5,
 p_version_note => 'Workflow overview: first release',
 p_body => $body${"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Direct screen links"}]},{"type":"paragraph","content":[{"type":"text","text":"These links target the "},{"type":"text","text":"portal's current route structure","marks":[{"type":"bold"}]},{"type":"text","text":". Dynamic record screens must be opened from their parent list; a link to a list cannot identify an individual record."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Copy","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/underwriting/copy"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Place a credit","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/underwriting/contracts"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Affidavits","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/underwriting/affidavits"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Exceptions","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/underwriting/exceptions"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Contracts","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/underwriting/contracts"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dashboard","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/underwriting"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Migration","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/underwriting/setup/migration"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"DAD log","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/log/dad-log"}}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Purpose and handoffs"}]},{"type":"paragraph","content":[{"type":"text","text":"Traffic turns an approved underwriting agreement into a measurable broadcast obligation. The essential chain is "},{"type":"text","text":"signed order → contract and flights → scheduled demand → approved copy → placed credit → broadcast verification → exception or fulfillment → affidavit","marks":[{"type":"bold"}]},{"type":"text","text":". A scheduled credit is not necessarily an aired credit. An approved script is not necessarily a recorded DAD cut."}]},{"type":"paragraph","content":[{"type":"text","text":"The underwriting or business team is accountable for accurate commercial terms, schedule and sponsor information. Traffic is accountable for correct placement and reconciliation. Production is accountable for recording required cuts. Managers handle designated exceptions and affidavit certification. Station procedures for processing underwriter card payments are separate from the Traffic tool; do not store card details in contract notes."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. Enter or reconcile a contract"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Find the organization and check for an existing contract before creating another."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Read the signed insertion order. Identify its date range, any distinct flights, inventory pools or named programs, duration, required total, weekly or daily quotas, exclusions, copy restrictions, separation rules, makegood approval requirements and affidavit terms."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enter the contract and its schedule so each line accurately expresses the obligation. "},{"type":"text","text":"Do not convert a three-per-week order into a daily credit merely because seven days are eligible.","marks":[{"type":"bold"}]},{"type":"text","text":" Period demand and eligibility are different."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Where an order includes explicit dates or a changing schedule, preserve those constraints rather than spreading credits across the entire campaign. Use the review warnings to flag inconsistencies in the source order; do not silently correct a signed document."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Attach the agreement and verify the entered figures against it. Complete the activation readiness checks. A draft does not schedule until activated."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Migrated agreements:","marks":[{"type":"bold"}]},{"type":"text","text":" Inspect the import and any unrecognized names or missing source documents. Treat migrated historical placements as provisional until reviewed against the actual order and run evidence. Do not infer an advertiser's consent to a makegood or substitution from a completed import."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. Prepare and approve copy"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"From the contract's "},{"type":"text","text":"**Copy** area","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/underwriting/copy"}}]},{"type":"text","text":", create a new message or link existing copy. Verify that the sponsor identification and script satisfy the order and station underwriting standards."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Associate approved messages with the correct contract, flight and, where stipulated, schedule line. A line-specific message must not rotate onto unrelated lines."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check the script's status, effective dates, duration, and DAD cut. "},{"type":"text","text":"Approved","marks":[{"type":"bold"}]},{"type":"text","text":" governs scheduling eligibility; "},{"type":"text","text":"recorded in DAD","marks":[{"type":"bold"}]},{"type":"text","text":" governs whether automation can play it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"For a newly assigned cut, record the message under the identified cut number and mark it recorded after checking the actual DAD asset. An existing DAD spot must be explicitly selected when the copy references one. Changing a cut or substantive wording can clear the recorded status."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Confirm the correct treatment for live reads during hosted hours and recorded playback during unattended hours. A new live read is not automatically ready for automated playback."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Rotation example"}]},{"type":"paragraph","content":[{"type":"text","text":"Two approved messages with weights "},{"type":"text","text":"2","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"1","marks":[{"type":"bold"}]},{"type":"text","text":" should be distributed approximately two-to-one over eligible placements, rather than all instances of one followed by the other. Weights apply within the group of messages that rotate together (general contract copy or copy dedicated to a specific line); aired credits remain fixed and changing weights only resequences unaired credits. Review the current copy-rotation guide for exact controls."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. Place and verify credits"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check the line's remaining demand and eligible dates or inventory pools."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"**Place a credit**","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/underwriting/contracts"}}]},{"type":"text","text":" to select an available break and verify the proposed message. Manual placement may show adjacency warnings; these warnings are advisory and should still be considered."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use the available auto-fill scope (line, contract or all eligible active contracts) when appropriate. Auto-fill may provision the rundowns it needs. Its success must be checked against each line's period demand, not simply by counting total credits."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Distinguish the placement record from broadcast confirmation. Review outcomes and period fulfillment after air; resolve missed, preempted or otherwise disputed credits using the exception workflow."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Where agency approval is required for a makegood, record it before scheduling the substitution. Avoid using an available slot to conceal a contractual shortfall in a different week or flight."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Generate affidavits from confirmed fulfillment for the required period. Certification is manager-controlled and creates a fixed record; investigate discrepancies before certifying."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Unattended hours and DAD"}]},{"type":"paragraph","content":[{"type":"text","text":"Traffic's placement system and On Air's automation schedule are linked but not interchangeable."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On Air defines which hours are automated and which hours permit underwriting. An eligible contractual obligation does not override an hours-closed rule."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The DAD log includes playable breaks for unattended hours only; hosted hours remain the host's responsibility."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check the DAD log's pre-release warnings: missing or unrecorded cuts, unapproved or out-of-date messages, live-only elements and invalid timing can block release."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Traffic releases and downloads the generated day file, which must then reach DAD's import folder. "},{"type":"text","text":"A released export does not by itself prove DAD imported or aired it.","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If a rundown changes after release, examine the stale-release warning and generate a new version. Preserve the version trail."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Integration boundary:","marks":[{"type":"bold"}]},{"type":"text","text":" Verify the operational process for confirming DAD import and reconciling actual playout. The repository describes exported files and broadcast events, but this guide must not claim an automated ENCO return path without verifying it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"5. Troubleshooting and decisions"}]}]}$body$
);

select private.rc_release_guide(
 p_slug => 'on-air-workflow-overview',
 p_tool_key => 'log',
 p_title => 'On Air: daily workflows and automation',
 p_summary => 'Prepare rundowns, schedules and DAD releases.',
 p_screen_keys => array['log.today','log.library','log.dad-log'],
 p_sort_order => 5,
 p_version_note => 'Workflow overview: first release',
 p_body => $body${"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Host: prepare and run the daily rundown"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open "},{"type":"text","text":"**Today**","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/log"}}]},{"type":"text","text":" for the correct date and program. Review the program's schedule and assigned clock; confirm the rundown is for the broadcast hour actually being hosted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Review the planned content, slots and duration for each local break. Confirm the latest NPR material and weather sources have loaded before relying on their details; a populated field is not proof its source is current."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Identify items requiring a live read and items with playable DAD cuts. Check special instructions, sponsor copy and any fixed legal or station IDs. Do not replace pinned items ad hoc."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Before airtime, check whether a break is empty, overfilled, missing content, or otherwise incomplete. Resolve discrepancies with the producer or Traffic rather than assuming automation will fix them."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"During the program, follow the on-air rundown and record the actual disposition of items as supported by the host console. A scheduled underwriting credit is not equivalent to a confirmed airing."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"After the shift, communicate missed elements or deviations promptly so Traffic can resolve exceptions and the next host has accurate information."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Producer: plan content and review schedules"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Maintain reusable items in the "},{"type":"text","text":"**Content library**","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/log/library"}}]},{"type":"text","text":", including content type, title, script, duration, dates and DAD references where applicable."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use the selected program clock to place local content within defined slots, taking care not to confuse a floating break with a fixed item."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Review imported program logs and NPR source data before incorporating them; verify dates, timing and attribution."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Inspect generated rundowns in broadcast order. Check the beginning and end of breaks, fixed IDs, underwriting placements and available time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Communicate clock or schedule changes affecting Traffic. Review how changes affect future, already-released and aired material."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Operations: program clocks and schedule"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep each scheduled program associated with an appropriate clock. Verify clock versions and any floating opportunities before using them in a live schedule."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"**Schedule**","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/log/programs"}}]},{"type":"text","text":" for recurring program times and one-time changes; use "},{"type":"text","text":"**Automation**","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/log/automated-hours"}}]},{"type":"text","text":" to indicate unattended hours and "},{"type":"text","text":"**Underwriting hours**","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/log/underwriting-hours"}}]},{"type":"text","text":" to close otherwise available periods to traffic placements."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Distinguish programming, hosting and credit eligibility: an hour can be unattended yet closed to underwriting; automated status alone does not determine sellable inventory."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Confirm mandatory station IDs are pinned on the relevant clock as designed and that changed clocks still provide the required opportunities."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Review the effect of program, clock and hours changes on both host rundowns and the generated DAD log."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Traffic and Operations: release the DAD log"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open the day's "},{"type":"text","text":"**DAD log**","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/log/dad-log"}}]},{"type":"text","text":" and review automated hours, listed content and the raw file preview."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Resolve blockers: unrecorded or unassigned DAD cuts, missing approved copy, live-only content, timing overruns and other unsupported items. A missing rundown during automated hours deserves investigation even when presented as advisory."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Release the export using the tool's control, then download and deliver it to the actual ENCO/DAD import location following station practice."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If the underlying rundown changes afterward, inspect the out-of-date warning and release a new version. Keep older versions as an audit trail."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Verify import and playback using the station's established operational evidence. "},{"type":"text","text":"Export, import, and aired confirmation are three separate events.","marks":[{"type":"bold"}]},{"type":"text","text":" Do not assume an automated return/reconciliation feed unless engineering has verified it."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Failure and escalation"}]},{"type":"paragraph","content":[{"type":"text","text":"When the broadcast system is impaired, follow the station procedures for a total power failure, web-stream restart, Comrex routing, FPREN codec operation and HD3 source failure as applicable. These SOPs cover hardware and continuity response; this guide must not duplicate their technical recovery instructions."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Direct portal screen links"}]},{"type":"paragraph","content":[{"type":"text","text":"Open these routes in the portal. Individual records must be opened from their list; no record ID is assumed."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Today","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/log"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Content library","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/log/library"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Programs","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/log/programs"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Automation","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/log/automated-hours"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Underwriting hours","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/log/underwriting-hours"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"DAD log","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/log/dad-log"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sources","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/log/sources"}}]}]}]}]}]}$body$
);

select private.rc_release_guide(
 p_slug => 'sourcework-workflow-overview',
 p_tool_key => 'transcription',
 p_title => 'Sourcework: evidence-first reporting',
 p_summary => 'Organize source material and verify transcripts.',
 p_screen_keys => array['sourcework.projects','sourcework.project','sourcework.sources'],
 p_sort_order => 5,
 p_version_note => 'Workflow overview: first release',
 p_body => $body${"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Organize a project"}]},{"type":"paragraph","content":[{"type":"text","text":"Create a project for a clearly defined reporting question, not merely a dumping ground for files. Name it so another reporter can distinguish it from related work. Add or reference relevant sources through the existing "},{"type":"text","text":"**Source Library**","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/sourcework?tab=sources"}}]},{"type":"text","text":" and project workspace. Before uploading, verify permission to use or retain sensitive recordings and avoid adding material unrelated to the work."}]},{"type":"paragraph","content":[{"type":"text","text":"A source is the underlying recording or document. A transcript is a derived representation. An excerpt is a selected passage. The distinction matters: derived text must not silently replace the original when facts, attribution or exact wording are important."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Transcribe and verify"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Add a recording or source using the supported workspace controls, preserving sufficient context to know who, what and when it represents."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Review the resulting transcript alongside the original wherever the quotation, name, number or sequence is consequential."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Correct or annotate doubtful passages using the workspace's available editing mechanisms; do not convert uncertain transcription into a confident attributed quotation."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Create excerpts only with enough surrounding context to preserve meaning. When moving a passage into a story or production script, return to the source for final confirmation."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Distinguish errors introduced by transcription from contradictions in the source itself."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Find and reuse material"}]},{"type":"paragraph","content":[{"type":"text","text":"Search across projects and the Source Library to locate likely sources, then open the underlying result and verify its provenance. Search ranking and semantic similarity indicate relevance, not truth or permission to publish. When adding an existing source to another project, link to the same underlying asset where the tool allows rather than creating avoidable duplicates."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Editorial checks"}]},{"type":"paragraph","content":[{"type":"text","text":"Before publishing from an excerpt, verify exact words, speaker identification, dates, context, potential edits and the original audio or document. AI-assisted summarization is an aid to retrieval; it is not an independent source."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Direct portal screen links"}]},{"type":"paragraph","content":[{"type":"text","text":"Open these routes in the portal. Individual records must be opened from their list; no record ID is assumed."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Projects","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/sourcework"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Create project","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/sourcework/new"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Source Library","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/sourcework?tab=sources"}}]}]}]}]}]}$body$
);

select private.rc_release_guide(
 p_slug => 'editorial-planning-workflow-overview',
 p_tool_key => 'editorial-planning',
 p_title => 'Editorial Planning: pitch to assignment',
 p_summary => 'Prepare pitches, score and document decisions.',
 p_screen_keys => array['editorial.backlog','editorial.meeting','editorial.pitch'],
 p_sort_order => 5,
 p_version_note => 'Workflow overview: first release',
 p_body => $body${"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Submit a useful pitch"}]},{"type":"paragraph","content":[{"type":"text","text":"A pitch should make a potential story legible to a colleague without requiring a separate conversation. State what is happening; whom it affects; why it matters now; what remains unknown; what evidence or sources might answer the question; and what reporting effort is likely required. Choose the coverage pillar that best describes the underlying public question, not merely the institution involved."}]},{"type":"paragraph","content":[{"type":"text","text":"Example:","marks":[{"type":"bold"}]},{"type":"text","text":" Rather than \"UWF hosts military program,\" frame the public question: whether a university's expansion of military-to-civilian training is changing access to civilian employment and for whom. The institutional activity is a lead to investigate, not necessarily the story's conclusion."}]},{"type":"paragraph","content":[{"type":"text","text":"The existing workflow permits a "},{"type":"text","text":"submitted pitch","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/editorial"}}]},{"type":"text","text":" to be edited until it enters "},{"type":"text","text":"meeting scoring","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/editorial/meetings"}}]},{"type":"text","text":"; use review history to understand whether it was assigned, deferred or archived."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Run a planning meeting"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Editors create the meeting and select a rubric appropriate to the mix of coverage. Add eligible pitches to the slate."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reviewers score independently against the published anchored criteria and record substantive concerns. An institutional alignment modifier must not substitute for the story's civic value, evidence or feasibility."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"After scoring closes, consider the ranked agenda, disagreements and written comments. Scores inform editorial judgment; they do not make the assignment decision themselves."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Record the disposition and assignment clearly. A deferred pitch should have an understandable next step where possible; an assigned pitch should identify the responsible reporter."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Conclude the meeting only after decisions are recorded. The concluded meeting is a permanent historical record."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Move from pitch to story plan"}]},{"type":"paragraph","content":[{"type":"text","text":"An assignment needs more than a reporter's name. Define the central reporting question, reporting steps, essential sources, verification needs, likely format, constraints and next editorial checkpoint. Avoid presenting a hypothesis as an established finding."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Administration"}]},{"type":"paragraph","content":[{"type":"text","text":"Configuration guides should explain the difference between weighted core criteria and separate modifiers, how archived rubric elements preserve historical scores, and when changing criteria is justified. Any numerical example must match the live rubric."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Direct portal screen links"}]},{"type":"paragraph","content":[{"type":"text","text":"Open these routes in the portal. Individual records must be opened from their list; no record ID is assumed."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pitch backlog","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/editorial"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Meetings","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/editorial/meetings"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Settings","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/editorial/settings"}}]}]}]}]}]}$body$
);

select private.rc_release_guide(
 p_slug => 'audience-listening-workflow-overview',
 p_tool_key => 'audience-listening',
 p_title => 'Audience Listening: from query to reporting',
 p_summary => 'Design queries, review responses and interpret submissions.',
 p_screen_keys => array['audience-listening.queries','audience-listening.query'],
 p_sort_order => 5,
 p_version_note => 'Workflow overview: first release',
 p_body => $body${"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Design a listening question"}]},{"type":"paragraph","content":[{"type":"text","text":"Start with a specific reporting uncertainty and ask what members of the public can usefully tell the newsroom from direct experience. Use open questions that do not imply an answer, conflate multiple issues, demand private information unnecessarily or promise editorial outcomes. The "},{"type":"text","text":"public query tool","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/audience-listening"}}]},{"type":"text","text":" supports a limited set of recorded questions; keep the sequence short enough to answer thoughtfully."}]},{"type":"paragraph","content":[{"type":"text","text":"Examples:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Less useful:","marks":[{"type":"bold"}]},{"type":"text","text":" \"Why has rising rent made the city unaffordable for everyone?\""}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"More useful:","marks":[{"type":"bold"}]},{"type":"text","text":" \"How, if at all, have changes in housing costs affected decisions you or your household made this year?\""}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The first assumes the conclusion; the second leaves room for differing experiences."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Publish and review"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Draft the query and review its public wording, recording experience and any consent/privacy notices before publication."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Share it through channels capable of reaching the audiences whose experiences matter; document obvious gaps in who is likely to encounter it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Review incoming submissions for relevance, safety, follow-up potential and the limits of the speaker's firsthand knowledge."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Where a response merits reporting, seek corroboration and direct follow-up; do not treat a compelling recording as verified fact."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Send relevant responses to Sourcework using the existing handoff, keeping the originating query and source attribution linked."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Interpret findings"}]},{"type":"paragraph","content":[{"type":"text","text":"Responses gathered through an open public prompt are "},{"type":"text","text":"not a representative poll","marks":[{"type":"bold"}]},{"type":"text","text":". Do not equate the number of responses with prevalence across the coverage area. Note who was reached, who was not, which experiences recur and which observations merit additional reporting. Protect sensitive personal details and honor the actual consent terms presented to respondents."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Close the loop"}]},{"type":"paragraph","content":[{"type":"text","text":"Where appropriate, explain what questions the newsroom heard and how they shaped subsequent coverage; do not imply that every submission will be broadcast or receive an individual response."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Direct portal screen links"}]},{"type":"paragraph","content":[{"type":"text","text":"Open these routes in the portal. Individual records must be opened from their list; no record ID is assumed."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Queries","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/audience-listening"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"New query","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/audience-listening/new"}}]}]}]}]}]}$body$
);

select private.rc_release_guide(
 p_slug => 'roadmap-workflow-overview',
 p_tool_key => 'roadmap',
 p_title => 'Roadmap: requests and decisions',
 p_summary => 'Write requests, triage and track decisions.',
 p_screen_keys => array['roadmap.board','roadmap.post'],
 p_sort_order => 5,
 p_version_note => 'Workflow overview: first release',
 p_body => $body${"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Submit a request"}]},{"type":"paragraph","content":[{"type":"text","text":"Explain the problem before proposing a feature. Include the workflow affected, who experiences the problem, the consequence, a concrete example and what a successful change would allow. Distinguish a defect in existing behavior from a proposed improvement and avoid putting passwords or confidential production data in a request."}]},{"type":"paragraph","content":[{"type":"text","text":"Example:","marks":[{"type":"bold"}]},{"type":"text","text":" Instead of \"Make Traffic better,\" explain: \"When the agreement specifies three credits per week, I cannot tell on Tuesday whether the current week has met the required count. I need a line-level weekly progress view, including aired and outstanding credits.\""}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Triage and discussion"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Roadmap board","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/roadmap"}}]},{"type":"text","text":" is a channel for collecting and curating product work, not a guarantee of implementation or delivery date. Administrators should identify duplicate requests, ask for missing context, group related work, and distinguish confirmed needs from possible solutions. Comments should add evidence or a materially different use case rather than simply repeat support."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Interpret status"}]},{"type":"paragraph","content":[{"type":"text","text":"Read the current card or request page for its actual status and discussion. Do not infer that a popular proposal is approved or that a proposed change is ready to deploy. When a request becomes implemented, link the relevant release note or tool guide so the original requester can learn what changed."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Direct portal screen links"}]},{"type":"paragraph","content":[{"type":"text","text":"Open these routes in the portal. Individual records must be opened from their list; no record ID is assumed."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Board","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/roadmap"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"New request","marks":[{"type":"link","attrs":{"href":"https://tools.wuwf.org/roadmap/new"}}]}]}]}]}]}$body$
);

select private.rc_release_note(
 p_slug => 'release-2026-10-08-workflow-overviews',
 p_tool_key => null,
 p_released_on => '2026-10-08',
 p_title => 'New workflow guides for seven tools',
 p_guide_slugs => array['bookings-workflow-overview','traffic-workflow-overview','on-air-workflow-overview','sourcework-workflow-overview','editorial-planning-workflow-overview','audience-listening-workflow-overview','roadmap-workflow-overview'],
 p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Seven new workflow guides for Bookings, Traffic, On Air, Sourcework, Editorial Planning, Audience Listening and Roadmap. Existing detailed guides remain available."}]}]}$body$
);
